 [DefaultExecutionOrder(-10000)]public sealed class Part12AProbe:MonoBehaviour
 {
  const string Output="docs/ProductionReports/Part12A/";public bool reload;static Part12AProbe active;string key,root;readonly List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();readonly Dictionary<string,string> player=new Dictionary<string,string>();readonly List<GeneratedLevel> examples=new List<GeneratedLevel>();int preparationFrames;float prepareSeconds;
  void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);foreach(var suffix in new[]{"",".backup",".corrupt"}){var k=GameplayProgress.StorageKey+suffix;player[k]=PlayerPrefs.HasKey(k)?PlayerPrefs.GetString(k):null;}key=SessionState.GetString("Part12A.Key","");root=SessionState.GetString("Part12A.Archive","");GameplayLevelCatalog.TestArchive=new FileLevelArchive(root);Bind(key);if(!reload){GameplayProgress.Current.Claim(1,3,true,out _);GameplayProgress.Current.Claim(2,3,true,out _);GameplayProgress.Current.SetCurrentLevel(2);}GameplayLevelCatalog.ResumeFromSave();Application.logMessageReceived+=Log;}
  void Bind(string profile){GameplayProgress.UseTestProfile();typeof(GameplayProgress).GetField("current",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,GameplayProgress.Open(profile));}
  void Log(string m,string s,LogType t){if(t==LogType.Warning)warnings.Add(m);if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);}
