  PrototypeApp App=>FindFirstObjectByType<PrototypeApp>();PawGuide Guide=>FindFirstObjectByType<PawGuide>();Puzzle Model=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(App);
  void Tap(string name){var go=GameObject.Find(name);Check(go!=null,"Buton: "+name);go.GetComponent<Button>().onClick.Invoke();}
  IEnumerator Start(){var stack=new Stack<IEnumerator>();stack.Push(reload?Reload():Run());string failure=null;while(stack.Count>0){object next=null;bool more=false;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){failure=e.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested&&!(next is CustomYieldInstruction)){stack.Push(nested);continue;}yield return next;}bool intact=player.All(p=>p.Value==null?!PlayerPrefs.HasKey(p.Key):PlayerPrefs.GetString(p.Key)==p.Value);Application.logMessageReceived-=Log;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();GameplayLevelCatalog.TestArchive=null;File.WriteAllText(Output+(reload?"RELOAD_TESTS.json":"UNITY_TESTS.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{success=failure==null&&errors.Count==0&&intact,failure,checks,errors,warnings,playerSaveAndBackupIntact=intact,preparationFrames,prepareSeconds},Newtonsoft.Json.Formatting.Indented));if(!reload)File.WriteAllText(Output+"EXAMPLES.json",Newtonsoft.Json.JsonConvert.SerializeObject(examples,Newtonsoft.Json.Formatting.Indented));if(reload||failure!=null){foreach(var profile in new[]{key,key+".tutorial"})foreach(var suffix in new[]{"",".backup",".corrupt"})PlayerPrefs.DeleteKey(profile+suffix);PlayerPrefs.Save();string prefix=Path.GetFullPath(Path.Combine(Path.GetTempPath(),"Mewgic-Part12A-QA-"));if(Path.GetFullPath(root).StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&Directory.Exists(root))Directory.Delete(root,true);}EditorApplication.isPlaying=false;}
  IEnumerator WaitLevel(int id){float until=Time.unscaledTime+15;do{yield return null;}while(Time.unscaledTime<until&&(SceneManager.GetActiveScene().name!="Gameplay"||App==null||Guide==null||GameplayLevelCatalog.SelectedId!=id));yield return null;yield return null;Check(Guide!=null&&GameplayLevelCatalog.SelectedId==id,"Gerçek Gameplay bölümü: "+id);}
  IEnumerator Prepare(int id){float start=Time.unscaledTime;var task=GameplayLevelCatalog.PrepareAsync(id);while(!task.IsCompleted){preparationFrames++;yield return null;}prepareSeconds+=Time.unscaledTime-start;Check(!task.IsFaulted,"Asenkron üretim/sertifika: "+id);}
  void Shots(string name){foreach(int h in new[]{1600,1950,2000})Capture(Output+name+(h==1600?"":"-"+h)+".png",900,h,h==2000);}
  IEnumerator Solve(){var solution=PuzzleSolver.Solve(Model.Export());Check(solution.Status==SearchStatus.Solved,"Aktif durum solver ile çözüldü");foreach(var m in solution.Moves){Tap("Bottle "+(m.Source+1));Tap("Bottle "+(m.Target+1));yield return new WaitForSecondsRealtime(1.05f);}Check(Model.Won&&FindFirstObjectByType<GameplayEndScreen>().IsShowing,"Gerçek aktarım ile kazanma paneli");}
  IEnumerator Run()
  {
   yield return WaitLevel(2);Check(Model.Count==5&&!Guide.Visible,"Eski bölüm 2/pati geçmişi korunur");Guide.Close();yield return Solve();Tap("NextLevel");yield return WaitLevel(3);var easy=GameplayLevelCatalog.Current();Check(easy.Generated!=null&&easy.Generated.difficulty.measured==LevelDifficulty.Easy&&LevelGenerator.Exact(Model.Export(),easy.Bottles),"Bölüm 2→3 gerçek prosedürel kolay bölüm");examples.Add(easy.Generated.Copy());Shots("Generated_Easy");var start=Model.Export();var move=easy.Generated.solution[0];Tap("Bottle "+(move.source+1));Tap("Bottle "+(move.target+1));yield return new WaitForSecondsRealtime(1.05f);Tap("Undo");Check(Model.Moves==0&&LevelGenerator.Exact(Model.Export(),start),"Üretilmiş bölüm Undo");Tap("Restart");Check(LevelGenerator.Exact(Model.Export(),start),"Restart aynı seed/düzen");int hints=GameplayProgress.Current.Remaining(BoosterKind.Hint);Tap("Hint");Check(GameplayProgress.Current.Remaining(BoosterKind.Hint)==hints-1&&FindObjectsByType<HintCueGraphic>(FindObjectsSortMode.None).Length==2,"Prosedürel Hint doğrulanmış metinsiz hamle");Tap("Restart");Tap("Shuffle");Check(PuzzleSolver.Solve(Model.Export()).Status==SearchStatus.Solved,"Gameplay Shuffle çözülebilir");Tap("ExtraBottle");Check(Model.Count==start.Length+1,"Ek şişe mevcut kurala bağlı");Tap("Restart");Check(Model.Count==start.Length&&LevelGenerator.Exact(Model.Export(),start),"Restart ek şişeden sonra da orijinal pin");Tap("Pause");Check(App.IsPaused,"Pause");Tap("Resume");yield return Solve();Tap("NextLevel");yield return WaitLevel(4);Check(GameplayLevelCatalog.Current().Generated!=null,"Ardışık üretilmiş bölüm geçişi 3→4");
   yield return Prepare(8);GameplayProgress.Current.Claim(7,3,true,out _);Check(GameplayLevelCatalog.Select(8,GameplayProgress.Current),"Normal örneğe yalnız QA profilinde erişim");SceneManager.LoadScene("Gameplay");yield return WaitLevel(8);var normal=GameplayLevelCatalog.Current();Check(normal.Generated.difficulty.measured==LevelDifficulty.Normal,"Ölçülmüş Normal örnek");examples.Add(normal.Generated.Copy());Shots("Generated_Normal");
   yield return Prepare(20);GameplayProgress.Current.Claim(19,3,true,out _);Check(GameplayLevelCatalog.Select(20,GameplayProgress.Current),"Hard örneğe yalnız QA profilinde erişim");SceneManager.LoadScene("Gameplay");yield return WaitLevel(20);var hard=GameplayLevelCatalog.Current();Check(hard.Generated.difficulty.measured==LevelDifficulty.Hard,"Ölçülmüş Hard örnek");examples.Add(hard.Generated.Copy());Shots("Generated_Hard");string pinned=hard.Generated.signature;Bind(key);GameplayLevelCatalog.ResumeFromSave();SceneManager.LoadScene("Gameplay");yield return WaitLevel(20);Check(GameplayLevelCatalog.Current().Generated.signature==pinned,"Kayıt yeniden açılınca aynı açılmış pin");
   yield return Prepare(21);string file=Path.Combine(root,"level-20.json"),originalPin=File.ReadAllText(file),originalBackup=File.ReadAllText(file+".backup");File.WriteAllText(file,"broken");File.WriteAllText(file+".backup","broken");SceneManager.LoadScene("Home");yield return null;yield return null;Tap("Play");yield return new WaitForSecondsRealtime(1);Check(SceneManager.GetActiveScene().name=="Home"&&GameObject.Find("LevelPreparationNotice")!=null,"İki bozuk pin Home'da güvenli tekrar deneme mesajı; rastgele oynanış yok");File.WriteAllText(file,originalPin);File.WriteAllText(file+".backup",originalBackup);Tap("Play");yield return WaitLevel(20);Check(GameplayLevelCatalog.Current().Generated.signature==pinned,"Hata sonrası yeniden deneme özgün pin'i kullanır");
   // First-level mascot now uses the canonical BFS without changing its real moves.
   Bind(key+".tutorial");GameplayLevelCatalog.ResetSelection();SceneManager.LoadScene("Gameplay");yield return WaitLevel(1);float until=Time.unscaledTime+12;while(Guide.DemoRunning&&Time.unscaledTime<until)yield return null;Check(!Guide.DemoRunning&&GameplayProgress.Current.TutorialCompleted(PawGuide.BasicId)&&Model.Moves==1,"Pati yeni solver ile gerçek doğrulanmış örneği tamamladı");
   Bind(key);GameplayLevelCatalog.ResumeFromSave();SceneManager.LoadScene("Gameplay");yield return WaitLevel(20);SessionState.SetString("Part12A.Expected",JsonUtility.ToJson(GameplayProgress.Current.Snapshot));SessionState.SetString("Part12A.Pin",GameplayLevelCatalog.Current().Generated.signature);Check(preparationFrames>0,"Üretim ana iş parçacığını bekletmeden kareler ilerledi");
  }
  IEnumerator Reload(){float until=Time.unscaledTime+15;while(SceneManager.GetActiveScene().name!="Home"&&Time.unscaledTime<until)yield return null;Check(SceneManager.GetActiveScene().name=="Home","Gerçek Boot generated pin ile Home'a ulaştı");Tap("Play");yield return WaitLevel(20);Check(JsonUtility.ToJson(GameplayProgress.Current.Snapshot)==SessionState.GetString("Part12A.Expected",""),"İki Play Mode/Boot arasında bütün kayıt aynı");Check(GameplayLevelCatalog.Current().Generated.signature==SessionState.GetString("Part12A.Pin","")&&!Guide.Visible,"Disk pin/sürüm yolu aynı; gereksiz öğretici yok");}
  void Clean(string label){Check(!FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).Any(t=>t.enabled&&(t.text.Contains("Altın kaynak")||t.text.Contains("mavi hedef")||t.text.Contains("→"))),label+": teknik ipucu metni yok");}
  void AuditLayout(RectTransform safe,int height){var views=FindObjectsByType<GameplayBottleView>(FindObjectsSortMode.None);foreach(var v in views){var c=new Vector3[4];v.Rig.GetWorldCorners(c);var min=(Vector2)safe.InverseTransformPoint(c[0]);var max=(Vector2)safe.InverseTransformPoint(c[2]);Check(min.x>=safe.rect.xMin&&max.x<=safe.rect.xMax&&min.y>=safe.rect.yMin&&max.y<=safe.rect.yMax,"Şişe Safe Area içinde "+height);}foreach(var t in FindObjectsByType<TMP_Text>(FindObjectsSortMode.None))if(t.enabled){t.ForceMeshUpdate();Check(!t.isTextOverflowing,"UI metni taşmıyor "+t.name+height);}}
        void Capture(string filename,int width,int height,bool inset=false)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var p=FindFirstObjectByType<HomeCharacterPresenter>();var safe=p!=null?(RectTransform)p.transform.Find("UI"):(GameObject.Find("Safe area")??GameObject.Find("MapSafeArea"))?.GetComponent<RectTransform>();
            var mode=canvas.renderMode;var oldCam=canvas.worldCamera;float distance=canvas.planeDistance;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;Vector2 min=safe!=null?safe.anchorMin:Vector2.zero,max=safe!=null?safe.anchorMax:Vector2.one;
            var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);
            try{
                camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;if(inset&&safe!=null){safe.anchorMin=new Vector2(.035f,.04f);safe.anchorMax=new Vector2(.965f,.955f);}
                Canvas.ForceUpdateCanvases();var gameplay=FindFirstObjectByType<GameplayPresentation>();if(gameplay!=null)gameplay.Layout();var pause=GameObject.Find("PauseSafeArea");if(pause!=null&&safe!=null){var pr=(RectTransform)pause.transform;pr.anchorMin=safe.anchorMin;pr.anchorMax=safe.anchorMax;}if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map!=null)map.Layout();var daily=FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>();if(daily!=null&&daily.IsOpen)daily.Layout();var hub=FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>();if(hub!=null&&hub.IsOpen)hub.Layout();Canvas.ForceUpdateCanvases();
                foreach(var text in FindObjectsByType<TMPro.TMP_Text>(FindObjectsSortMode.None))text.ForceMeshUpdate();FindFirstObjectByType<Mewgic.UI.PawGuide>()?.SendMessage("LateUpdate");foreach(var text in FindObjectsByType<TMP_Text>(FindObjectsSortMode.None)){text.ForceMeshUpdate();if(text.name=="PawMessage")Check(!text.isTextOverflowing,"Pati balonunda taşma yok: "+height);}AuditLayout(safe,height);Clean("Görsel "+filename);camera.Render();foreach(var graphic in FindObjectsByType<PawSoftGraphic>(FindObjectsSortMode.None)){var mesh=graphic.canvasRenderer.GetMesh();Check(mesh!=null&&mesh.vertexCount>20,"Pati/balon gerçek çizim geometrisi: "+graphic.name);}RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(filename,tex.EncodeToPNG());
            }finally{camera.targetTexture=oldTarget;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;if(safe!=null){safe.anchorMin=min;safe.anchorMax=max;}RenderTexture.active=oldActive;DestroyImmediate(tex);rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}}
        }
